    ('fe4edbed-be84-4b80-b5de-62ab3e4c88ef'::uuid, 'raw_data', '{"description_citations": [{"n": 1, "url": "https://www.isula.corsica/patrimoine/Les-sites-archeologiques-du-pianu-de-Cauria_a11.html", "claim": "A Figa is a Neolithic archaeological site in Corsica dating to 4500-3000 BC, located near Sartène", "title": "Les sites archéologiques du pianu de Cauria", "domain": "isula.corsica"}], "_description_provenance": {"v": 1, "ai": "generated", "lane": "L", "basis": "description differs from pre-March snapshot d4526691 (plan section 15.3)", "ai_system": "2026-03 enrichment chain (LLM; model per site not recorded)", "desc_sha256": "814e294710b8bd01eacc1108cb7c1a3852620137d0de27ea8645a3f2892c4b37"}}', '{"description_citations": [{"n": 1, "url": "https://www.isula.corsica/patrimoine/Les-sites-archeologiques-du-pianu-de-Cauria_a11.html", "claim": "A Figa is a Neolithic archaeological site in Corsica dating to 4500-3000 BC, located near Sartène", "title": "Les sites archéologiques du pianu de Cauria", "domain": "isula.corsica"}], "_description_provenance": {"v": 1, "ai": "generated", "lane": "L", "basis": "description differs from pre-March snapshot d4526691 (plan section 15.3)", "ai_system": "2026-03 enrichment chain (LLM; model per site not recorded)", "desc_sha256": "c63321ecfa559f6b1c38330ab7848d62702a0fb4a8f454c192c4765f3419e735"}}', 'dangling-markers:fe4edbed-be84-4b80-b5de-62ab3e4c88ef:raw_data', 'dangling-markers (provenance-hash): _description_provenance.desc_sha256 814e294710b8bd01eacc1108cb7c1a3852620137d0de27ea8645a3f2892c4b37 -> c63321ecfa559f6b1c38330ab7848d62702a0fb4a8f454c192c4765f3419e735, the sha256 of the new description (D4); description_citations unchanged; every other raw_data key stays as it is', '{"v": 1, "ai": "generated", "lane": "L", "basis": "description differs from pre-March snapshot d4526691 (plan section 15.3)", "ai_system": "2026-03 enrichment chain (LLM; model per site not recorded)"}', '[{"source": "acceptance:D4", "url": "scripts/remediation/acceptance/checks.py", "quote": "desc_sha256 must be the sha256 of the served description"}, {"source": "unified_sites.raw_data.description_citations", "url": "remediation_change_log.old_value", "quote": "removed: nothing"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 6;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _dangling_markers_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'dangling marker removal: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _dangling_markers_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'description' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.new_value IS NULL OR p.old_value IS NULL
                WHEN 'raw_data' THEN p.new_value::jsonb IS NOT DISTINCT FROM p.old_value::jsonb OR p.new_value IS NULL OR p.old_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'dangling marker removal: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _dangling_markers_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'description' THEN u.description IS DISTINCT FROM p.old_value::text
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.old_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'dangling marker removal: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _dangling_markers_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce((u.raw_data -> '_description_provenance') - 'desc_sha256', 'null'::jsonb)::text) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'dangling marker removal: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _dangling_markers_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'T08/dangling-markers', '2026-09-25_mechanical-dangling-markers', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'dangling marker removal: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _dangling_markers_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'description' THEN u.description IS DISTINCT FROM p.new_value::text
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.new_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'dangling marker removal: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _dangling_markers_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-09-25_mechanical-dangling-markers'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'dangling marker removal: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-09-25_mechanical-dangling-markers'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('description', 'raw_data'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'dangling marker removal: this run stamp journalled % row(s) outside unified_sites.(description, raw_data)', bad;
    END IF;

    RAISE NOTICE 'dangling marker removal: % of % planned cell(s) changed and journalled over 3 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-09-25_mechanical-dangling-markers'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'T08/dangling-markers'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = '2026-09-25_mechanical-dangling-markers' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('description', 'raw_data')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'description' THEN u.description IS NOT DISTINCT FROM l.new_value::text
                WHEN 'raw_data' THEN u.raw_data IS NOT DISTINCT FROM l.new_value::jsonb
                ELSE false END)
UNION ALL
SELECT 'curated rows D1 fails on (a marker without an entry, or an entry no marker cites)', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND (EXISTS (SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(raw_data -> 'description_citations') = 'array' THEN raw_data -> 'description_citations' ELSE '[]'::jsonb END) AS e(entry) WHERE NOT EXISTS (SELECT 1 FROM regexp_matches(coalesce(description, ''), '\[(\d+)\]', 'g') AS m(g) WHERE jsonb_typeof(e.entry -> 'n') = 'number' AND (e.entry ->> 'n')::numeric = m.g[1]::numeric)) OR EXISTS (SELECT 1 FROM regexp_matches(coalesce(description, ''), '\[(\d+)\]', 'g') AS m(g) WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(raw_data -> 'description_citations') = 'array' THEN raw_data -> 'description_citations' ELSE '[]'::jsonb END) AS e(entry) WHERE jsonb_typeof(e.entry -> 'n') = 'number' AND (e.entry ->> 'n')::numeric = m.g[1]::numeric)))
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
